package dev.mcpmcp.core;
import com.google.gson.*;
import java.util.*;
/** Preflight checks run before a container is opened or any item is picked up. */
public final class ContainerContract {
 public static int count(JsonObject a){int n=Jsons.integer(a,"count",-1);if(n==0||n< -1)throw new IllegalArgumentException("count_must_be_positive_or_minus_one");return n;}
 public static void steps(JsonArray steps){if(steps.size()==0||steps.size()>64)throw new IllegalArgumentException("invalid_container_steps_count");for(JsonElement value:steps){if(!value.isJsonObject())throw new IllegalArgumentException("step_object_required");JsonObject s=value.getAsJsonObject();String op=Jsons.str(s,"op","click");Set<String> allowed=switch(op){case "click"->Set.of("op","slot","button","click","expected_item","expected_carried");case "wait"->Set.of("op","ticks");case "wait_result"->Set.of("op","slot","timeout_ticks");case "recipe"->Set.of("op","recipe_id","all");case "button"->Set.of("op","button");case "rename"->Set.of("op","text");default->throw new IllegalArgumentException("unknown_container_step");};for(String key:s.keySet())if(!allowed.contains(key))throw new IllegalArgumentException("unknown_step_field_"+key);if(Set.of("click","wait_result").contains(op)&&Jsons.integer(s,"slot",-1)<0)throw new IllegalArgumentException("step_slot_required");if(op.equals("click")){String type=Jsons.str(s,"click","pickup");if(!Set.of("pickup","quick_move","swap","throw","pickup_all").contains(type))throw new IllegalArgumentException("unsupported_click");int b=Jsons.integer(s,"button",0);if(type.equals("swap")?!(b>=0&&b<=8||b==40):b<0||b>1)throw new IllegalArgumentException("invalid_button");}if(op.equals("wait")&&(Jsons.integer(s,"ticks",2)<1||Jsons.integer(s,"ticks",2)>1200))throw new IllegalArgumentException("invalid_wait_ticks");if(op.equals("recipe")&&Jsons.str(s,"recipe_id","").isBlank())throw new IllegalArgumentException("recipe_id_required");if(op.equals("rename")&&Jsons.str(s,"text","").length()>50)throw new IllegalArgumentException("name_too_long");}Schema.bounded(steps);}
 private ContainerContract(){}
}
